import numpy as np,itertools
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
D=np.load('/app/output/calibration.npz');q=D['q'][:7];Jobs=D['J'];
def dh(q,alpha,offset):
 T=np.eye(4)
 for i in range(7):
  c=np.cos(q[i]);s=np.sin(q[i]);ca=np.cos(alpha[i]);sa=np.sin(alpha[i]);
  A=np.array([[c,-s*ca,s*sa,0],[s,c*ca,-c*sa,0],[0,sa,ca,offset[i]],[0,0,0,1]])
  T=T@A
 return T

def jac(q,alpha,offset,tip):
 p=[]
 for i in range(7):
  a=q.copy();a[i]+=.0001
  b=q.copy();b[i]-=.0001
  pa=dh(a,alpha,offset)@np.r_[tip,1];pb=dh(b,alpha,offset)@np.r_[tip,1]
  p.append((pa[:3]-pb[:3])/.0002)
 return np.array(p).T

variants=[[-1,1,1,-1,-1,1,0],[1,-1,-1,1,1,-1,0],[-1,1,-1,1,-1,1,0],[1,-1,1,-1,1,-1,0]]
for v in variants:
 alpha=np.array(v)*np.pi/2
 best=[]
 for bits in itertools.product([-1,1],repeat=6):
  signs=np.r_[1,bits];qq=q*signs
  def fun(x):
   tip=x[1:4];rot=Rotation.from_euler('z',x[0]).as_matrix();J=rot@jac(qq,alpha,[.36,0,.42,0,.4,0,.126],tip)@np.diag(signs)
   return (J-Jobs).ravel()
  sol=least_squares(fun,[0,0,0,.12],max_nfev=30)
  best.append((np.linalg.norm(sol.fun),signs,sol.x))
 best.sort(key=lambda t:t[0]);print('variant',v)
 for err,sg,x in best[:3]:print(round(err,4),sg,np.round(x,3))
